import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NamespaceResolver#seal()
 */
public class NamespaceResolver_seal_TriageGen0Test {





    @Test
    public void testSealMultipleLevels() {
        // Arrange
        NamespaceResolver grandParent = new NamespaceResolver();
        NamespaceResolver parent = new NamespaceResolver(grandParent);
        NamespaceResolver child = new NamespaceResolver(parent);

        // Act
        child.seal();

        // Assert
        assertTrue("Child should be sealed", child.isSealed());
        assertTrue("Parent should be sealed", parent.isSealed());
        assertTrue("Grandparent should be sealed", grandParent.isSealed());
    }


}

package org.apache.commons.jxpath.ri;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.model.NodeIterator;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NamespaceResolver#seal()
 */
public class NamespaceResolver_seal_TriageGen0Test {







    @Test
    public void testSealIdempotency() {
        // Arrange
        NamespaceResolver resolver = new NamespaceResolver();

        // Act
        resolver.seal();
        boolean firstSeal = resolver.isSealed();
        resolver.seal();
        boolean secondSeal = resolver.isSealed();

        // Assert
        assertTrue(firstSeal);
        assertTrue(secondSeal);
    }
}
